import pandas as pd
result = (
    Table_0
    .loc[lambda d: (
        d['Tipus'].str.lower() == 'total'
        ) & (
        d['Ciutat/altre'].str.lower().isin(['valència', 'barcelona'])
        ) & (
        d['Any'].isin([2021, 2022])
    )]
    .replace({'---': pd.NA})
    .assign(**{
        col: lambda d, c=col: pd.to_numeric(
            d[c].astype(str).str.replace(' ', ''), errors='coerce'
        )
        for col in ['1er Trimestre', '2n Trimestre', '3er Trimestre', '4t Trimestre']
    })
    .assign(row_avg=lambda d: d[[
        '1er Trimestre', '2n Trimestre', '3er Trimestre', '4t Trimestre'
    ]].mean(axis=1, skipna=True))
    .groupby('Ciutat/altre')
    .apply(lambda g: pd.Series({
        'avg_price_2021': g.loc[g['Any'] == 2021, 'row_avg'].mean(),
        'avg_price_2022': g.loc[g['Any'] == 2022, 'row_avg'].mean()
    }))
    .reset_index()
    .assign(price_change=lambda d: d['avg_price_2022'] - d['avg_price_2021'])
)
